const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const uid=(p='id')=>`${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
const clone=v=>JSON.parse(JSON.stringify(v));
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const nowStamp=()=>new Date().toISOString();
const safeFileName=s=>String(s||'cockpit').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80)||'cockpit';
const downloadBlob=(name,blob)=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1200)};
const icon=(name,cls='')=>`<img src="${name}.png" class="${cls}" alt="" aria-hidden="true">`;
const toast=msg=>{let el=$('#appToast');if(!el){el=document.createElement('div');el.id='appToast';Object.assign(el.style,{position:'fixed',zIndex:500,left:'50%',bottom:'90px',transform:'translateX(-50%)',padding:'9px 13px',border:'1px solid rgba(201,155,85,.6)',borderRadius:'10px',background:'rgba(18,14,11,.95)',color:'#f2e6cf',fontSize:'10px',boxShadow:'0 10px 28px rgba(0,0,0,.4)',transition:'.2s'});document.body.appendChild(el)}el.textContent=msg;el.style.opacity='1';clearTimeout(toast._t);toast._t=setTimeout(()=>el.style.opacity='0',2200)};

function askConfirm(message){return new Promise(resolve=>{const d=$('#confirmDialog');$('#confirmDialogMessage').textContent=message;const yes=$('#confirmDialogYes'),no=$('#confirmDialogNo');const finish=v=>{yes.onclick=null;no.onclick=null;if(d.open)d.close();resolve(v)};yes.onclick=()=>finish(true);no.onclick=()=>finish(false);d.showModal()})}

