function normalizeCharacter(c){
  const x=clone(c||DEMO);x.version=APP_VERSION;x.id=x.id||uid('char');x.name=x.name||'Personnage';x.subtitle=x.subtitle||'';x.species=x.species||'';x.className=x.className||'';x.level=Number(x.level||1);x.subclass=x.subclass||'';x.portrait=x.portrait||'wonq-demo.png';x.attuneColor=x.attuneColor||'#c69a55';x.hp=x.hp||{current:1,max:1,temp:0};x.abilities=x.abilities||{};x.passives=x.passives||{};x.skills=Array.isArray(x.skills)?x.skills:[];x.attacks=Array.isArray(x.attacks)?x.attacks:[];x.resources=Array.isArray(x.resources)?x.resources:[];x.features=Array.isArray(x.features)?x.features:[];x.tales=Array.isArray(x.tales)?x.tales:[];x.spells=Array.isArray(x.spells)?x.spells:[];x.items=Array.isArray(x.items)?x.items:[];x.journal=Array.isArray(x.journal)?x.journal:[];x.journal=x.journal.map(j=>({...j,pinned:!!j.pinned}));x.money=x.money||{pp:0,gp:0,sp:0,cp:0};x.slotMax=x.slotMax||{};x.slotUsed=x.slotUsed||{};x.spellFavorites=Array.isArray(x.spellFavorites)?x.spellFavorites:[];x.items=x.items.map(i=>({...i,value:i.value||'',charges:i.charges??'',maxCharges:i.maxCharges??''}));x.saveSlotId=x.saveSlotId||null;return x;
}
let state=normalizeCharacter(JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')||DEMO);
let currentView='home';let spellFilter='all';let selectedSpellId=state.spells[0]?.id||null;let inventoryFilter='all';let journalFilter='all';let illustrationFilter='all';let draggedItemId=null;let pointerDrag=null;let suppressItemClickUntil=0;let pendingBackgroundView=null;let currentItemId=null;let currentNoteId=null;
let illustrationSelected=new Set(),illustrationMoveMode=false,pendingIllustrationFiles=[];let illustrationObjectUrls=[];let portraitObjectUrl=null;const backgroundObjectUrls={};
function persist(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}
function getSlots(){try{return JSON.parse(localStorage.getItem(SLOTS_KEY)||'[]')}catch{return []}}
function setSlots(v){localStorage.setItem(SLOTS_KEY,JSON.stringify(v))}

/* ---------- IndexedDB media ---------- */
const DB_NAME='cockpit-player-media-v2',DB_VERSION=1;let dbPromise=null;
function openDb(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const db=r.result;for(const [name,key] of [['backgrounds','id'],['portraits','id'],['illustrations','id'],['meta','key']])if(!db.objectStoreNames.contains(name))db.createObjectStore(name,{keyPath:key})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return dbPromise}
async function dbGet(store,key){const db=await openDb();return new Promise((res,rej)=>{const r=db.transaction(store,'readonly').objectStore(store).get(key);r.onsuccess=()=>res(r.result||null);r.onerror=()=>rej(r.error)})}
async function dbAll(store){const db=await openDb();return new Promise((res,rej)=>{const r=db.transaction(store,'readonly').objectStore(store).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
async function dbPut(store,val){const db=await openDb();return new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(val);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
async function dbDelete(store,key){const db=await openDb();return new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}

/* ---------- Theme / backgrounds ---------- */
function applyTheme(id){if(!THEMES.some(x=>x.id===id))id='emerald';document.documentElement.dataset.theme=id;localStorage.setItem(THEME_KEY,id);renderThemes()}
async function getBackgroundUrl(view){if(backgroundObjectUrls[view])return backgroundObjectUrls[view];try{const r=await dbGet('backgrounds',view);if(r?.blob){const u=URL.createObjectURL(r.blob);backgroundObjectUrls[view]=u;return u}}catch(e){console.warn(e)}return DEFAULT_BACKGROUNDS[view]}
async function applyBackgrounds(){for(const view of Object.keys(DEFAULT_BACKGROUNDS)){const url=await getBackgroundUrl(view);const target=$(`#${view}View`);if(target)target.style.backgroundImage=`url("${url}")`;if(view==='home'&&$('#homeBackdrop'))$('#homeBackdrop').style.backgroundImage=`url("${url}")`}renderBackgroundRows()}
async function importBackground(view,file){if(!file||!file.type.startsWith('image/'))return;await dbPut('backgrounds',{id:view,blob:file,updatedAt:nowStamp()});if(backgroundObjectUrls[view]){URL.revokeObjectURL(backgroundObjectUrls[view]);delete backgroundObjectUrls[view]}await applyBackgrounds();toast(`Fond « ${BACKGROUND_LABELS[view]} » modifié`)}
async function resetBackground(view){await dbDelete('backgrounds',view);if(backgroundObjectUrls[view]){URL.revokeObjectURL(backgroundObjectUrls[view]);delete backgroundObjectUrls[view]}await applyBackgrounds();toast(`Fond « ${BACKGROUND_LABELS[view]} » réinitialisé`)}
async function renderBackgroundRows(){const el=$('#backgroundRows');if(!el)return;const html=[];for(const view of Object.keys(DEFAULT_BACKGROUNDS)){const url=await getBackgroundUrl(view);html.push(`<article class="background-row"><div class="background-preview" style="background-image:url('${url}')"></div><div class="background-row-body"><strong>${BACKGROUND_LABELS[view]}</strong><div class="background-actions"><button class="violet" data-bg-import="${view}">Changer</button><button class="ghost" data-bg-reset="${view}">Défaut</button></div></div></article>`)}el.innerHTML=html.join('');$$('[data-bg-import]').forEach(b=>b.onclick=()=>{pendingBackgroundView=b.dataset.bgImport;$('#backgroundImportFile').click()});$$('[data-bg-reset]').forEach(b=>b.onclick=()=>resetBackground(b.dataset.bgReset))}

/* ---------- portrait ---------- */
async function getPortraitUrl(){const key=`portrait:${state.id}`;try{const r=await dbGet('portraits',key);if(r?.blob){if(portraitObjectUrl)URL.revokeObjectURL(portraitObjectUrl);portraitObjectUrl=URL.createObjectURL(r.blob);return portraitObjectUrl}}catch(e){}return state.portrait||'wonq-demo.png'}
async function updatePortraits(){const url=await getPortraitUrl();$$('[data-character-portrait]').forEach(img=>img.src=url)}

/* ---------- navigation ---------- */
const VIEW_SEARCH_LABELS={home:'Rechercher…',sheet:'Caractéristique, compétence…',features:'Rechercher une aptitude…',spells:'Rechercher un sort…',inventory:'Rechercher un objet…',journal:'Rechercher une note…',illustrations:'Rechercher une illustration…'};
function switchView(view){const valid=['home','sheet','features','spells','inventory','journal','illustrations'];if(!valid.includes(view))view='home';currentView=view;for(const v of valid){const el=$(`#${v}View`);if(el)el.classList.toggle('hidden',v!==view)}$$('.nav-btn[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));renderTop();renderView(view)}
function renderView(v){if(v==='home')renderHomeDashboard();if(v==='sheet')renderSheet();if(v==='features')renderFeatures();if(v==='spells')renderSpells();if(v==='inventory')renderInventory();if(v==='journal')renderJournal();if(v==='illustrations')renderIllustrations()}
function renderTop(){document.documentElement.style.setProperty('--attune',state.attuneColor||'#c69a55');const label=$('#searchContextLabel');if(label)label.textContent=VIEW_SEARCH_LABELS[currentView]||'Rechercher…'}

/* ---------- home / slots ---------- */
function renderHomeSummary(){renderHomeDashboard()}
function renderThemes(){const cur=document.documentElement.dataset.theme;$('#themeChoices').innerHTML=THEMES.map(t=>`<button class="theme-choice ${t.id===cur?'active':''}" data-theme-choice="${t.id}"><span class="theme-swatches">${t.sw.map(c=>`<i style="background:${c}"></i>`).join('')}</span><strong>${t.name}</strong></button>`).join('');$$('[data-theme-choice]').forEach(b=>b.onclick=()=>applyTheme(b.dataset.themeChoice))}
function renderSlots(){const slots=getSlots();$('#characterSlotCount').textContent=`${slots.length} / ${MAX_CHARACTERS}`;const demo=`<article class="character-slot"><div><strong>Démo · Wonq</strong><small>Gardien des Absents · personnage intégré</small></div><div class="slot-actions"><button class="ghost" data-load-demo>Charger</button></div></article>`;$('#characterSlots').innerHTML=demo+slots.map(s=>`<article class="character-slot ${state.saveSlotId===s.id?'current':''}"><div><strong>${esc(s.name)}</strong><small>${esc(s.meta||'')} · ${new Date(s.updatedAt).toLocaleString('fr-FR')}</small></div><div class="slot-actions"><button class="primary" data-load-slot="${s.id}">Reprendre</button><button class="violet" data-export-slot="${s.id}">Exporter</button><button class="danger" data-delete-slot="${s.id}">×</button></div></article>`).join('');$('[data-load-demo]').onclick=()=>{state=normalizeCharacter(DEMO);state.saveSlotId=null;persist();renderAll();closeHome();toast('Démo Wonq chargée')};$$('[data-load-slot]').forEach(b=>b.onclick=()=>loadSlot(b.dataset.loadSlot));$$('[data-export-slot]').forEach(b=>b.onclick=()=>exportSlot(b.dataset.exportSlot));$$('[data-delete-slot]').forEach(b=>b.onclick=()=>deleteSlot(b.dataset.deleteSlot))}
function saveCurrentCharacter(){let slots=getSlots();if(state.saveSlotId){const i=slots.findIndex(x=>x.id===state.saveSlotId);if(i>=0){slots[i]={...slots[i],name:state.name,meta:`${state.species} · ${state.className} ${state.level}`,updatedAt:nowStamp(),state:clone(state)};setSlots(slots);renderSlots();toast('Personnage mis à jour');return}}if(slots.length>=MAX_CHARACTERS)return toast('20 personnages maximum');const id=uid('char-slot');state.saveSlotId=id;persist();slots.push({id,name:state.name,meta:`${state.species} · ${state.className} ${state.level}`,updatedAt:nowStamp(),state:clone(state)});setSlots(slots);renderSlots();toast('Personnage sauvegardé')}
function loadSlot(id){const s=getSlots().find(x=>x.id===id);if(!s)return;state=normalizeCharacter(s.state);state.saveSlotId=id;persist();renderAll();closeHome();toast(`${state.name} chargé`)}
async function deleteSlot(id){const slots=getSlots();const s=slots.find(x=>x.id===id);if(!s||!(await askConfirm(`Supprimer la sauvegarde « ${s.name} » ?`)))return;setSlots(slots.filter(x=>x.id!==id));if(state.saveSlotId===id)state.saveSlotId=null;persist();renderSlots()}
function characterPayload(c=state){const x=clone(c);x.saveSlotId=null;return {format:'cockpit-player-character',formatVersion:1,appVersion:APP_VERSION,exportedAt:nowStamp(),character:x}}
function exportSlot(id){const s=getSlots().find(x=>x.id===id);if(!s)return;const blob=new Blob([JSON.stringify(characterPayload(s.state),null,2)],{type:'application/json'});downloadBlob(`Cockpit-Joueur-${safeFileName(s.name)}.json`,blob)}
async function importCharacterFile(file){const raw=JSON.parse(await file.text());const c=normalizeCharacter(raw.character||raw);let slots=getSlots();if(slots.length>=MAX_CHARACTERS)throw new Error('20 personnages maximum');const id=uid('char-slot');c.id=uid('char');c.saveSlotId=id;slots.push({id,name:c.name,meta:`${c.species} · ${c.className} ${c.level}`,updatedAt:nowStamp(),state:c});setSlots(slots);renderSlots();toast(`${c.name} importé`)}
function openHome(section='characters'){$('#homeOverlay').classList.add('show');$('#homeOverlay').setAttribute('aria-hidden','false');renderSlots();renderThemes();renderBackgroundRows();requestAnimationFrame(()=>{const id=section==='theme'?'themeSettingsSection':section==='backgrounds'?'backgroundSettingsSection':'charactersSettingsSection';document.getElementById(id)?.scrollIntoView({block:'start'})})}
function closeHome(){$('#homeOverlay').classList.remove('show');$('#homeOverlay').setAttribute('aria-hidden','true')}

function renderHomeDashboard(){const root=$('#homeView');if(!root)return;const nav=[['sheet','👤','FICHE','Caractéristiques, compétences, profil'],['features','🧬','APTITUDES','Traits, dons, capacités'],['spells','🌀','SORTS','Emplacements, effets, rituels'],['inventory','🎒','INVENTAIRE','Équipement, objets, richesses'],['journal','📖','JOURNAL','Quêtes, notes, souvenirs'],['illustrations','🖼','ILLUSTRATIONS','Personnages, lieux, inspirations']];const theme=document.documentElement.dataset.theme||'emerald';root.innerHTML=`<div class="dashboard-v3"><div class="dashboard-art-spacer" aria-hidden="true"></div><section class="dashboard-core"><div class="dashboard-welcome"><span class="eyebrow">BIENVENUE</span><h1>${esc(state.name)}</h1><h2>${esc(state.role||state.subtitle||'Aventurier')}</h2><p>« ${esc(state.motto||'Chaque aventure commence par un choix.')} »</p></div><div class="dashboard-summary glass-panel"><div class="dashboard-level"><span>Niveau</span><b>${state.level}</b></div><div class="dashboard-stats">${[['Classe',state.className],['Ascendance',state.species],['CA',state.ac],['PV',`${state.hp.current}/${state.hp.max}`],['DD des sorts',state.spellDC],['Initiative',mod(state.initiative)],['Vitesse',state.speed],['Or',`${state.money.gp||0} PO`]].map(([l,v])=>`<div><span>${l}</span><b>${esc(v)}</b></div>`).join('')}</div></div><div class="dashboard-grid">${nav.map(([view,ico,title,sub])=>`<button class="dashboard-card" data-dashboard-view="${view}"><span class="dashboard-card-icon">${ico}</span><strong>${title}</strong><small>${sub}</small><i>›</i></button>`).join('')}</div></section><aside class="dashboard-theme glass-panel"><span class="eyebrow">THÈME VISUEL</span><h3>Choisissez votre ambiance</h3>${THEMES.slice(0,4).map(t=>`<button class="dashboard-theme-row ${t.id===theme?'active':''}" data-dashboard-theme="${t.id}"><span class="theme-swatches">${t.sw.map(c=>`<i style="background:${c}"></i>`).join('')}</span><b>${t.name}</b>${t.id===theme?'<small>Actif</small>':''}</button>`).join('')}<button class="ghost dashboard-more-themes" id="btnMoreThemes">⚙ Plus de thèmes</button></aside></div>`;$$('[data-dashboard-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.dashboardView));$$('[data-dashboard-theme]').forEach(b=>b.onclick=()=>{applyTheme(b.dataset.dashboardTheme);renderHomeDashboard()});$('#btnMoreThemes').onclick=()=>openHome('theme')}

/* ---------- sheet ---------- */
function mod(n){return Number(n)>=0?`+${n}`:String(n)}
function renderSheet(){
  const abilities=Object.entries(state.abilities),abilityIcons={FOR:'✊',DEX:'🪶',CON:'♥',INT:'📖',SAG:'◉',CHA:'♫'};
  const saves=abilities.map(([k,a])=>`<div class="save-row ${a.save!==a.mod?'proficient':''}"><span>${a.save!==a.mod?'●':'○'} ${k}</span><b>${mod(a.save)}</b></div>`).join('');
  $('#sheetView').innerHTML=`<div class="sheet-v3"><div class="sheet-art-spacer" aria-hidden="true"></div><section class="sheet-content-v3"><header class="screen-title-v3"><span class="eyebrow">IDENTITÉ · STATISTIQUES · COMPÉTENCES</span><h1>Fiche</h1></header><section class="identity-panel glass-panel"><img data-character-portrait src="${state.portrait}" alt="${esc(state.name)}"><div class="identity-main"><span class="eyebrow">${esc(state.subtitle||state.role||'PERSONNAGE')}</span><h2>${esc(state.name)}</h2><p>${esc(state.species)} · ${esc(state.className)} · Niveau ${state.level}</p><small>« ${esc(state.motto||'')} »</small></div><div class="identity-meta"><div><span>Origine</span><b>${esc(state.species)}</b></div><div><span>Classe</span><b>${esc(state.className)}</b></div><div><span>Voie</span><b>${esc(state.subclass||'—')}</b></div><div><span>Historique</span><b>${esc(state.background||'—')}</b></div><div><span>Alignement</span><b>${esc(state.alignment||'—')}</b></div></div></section><div class="ability-strip">${abilities.map(([k,a])=>`<div class="ability-card-v3"><span class="ability-icon">${abilityIcons[k]||'◆'}</span><strong>${k}</strong><b>${a.score}</b><em>${mod(a.mod)}</em></div>`).join('')}</div><div class="sheet-triple"><section class="glass-panel compact-panel"><div class="mini-head"><span>JETS DE SAUVEGARDE</span></div><div class="save-list">${saves}</div></section><section class="glass-panel compact-panel skills-panel-v3"><div class="mini-head"><span>COMPÉTENCES</span></div><div class="skills-list-v3">${state.skills.map(s=>`<div class="skill-row-v3"><span class="skill-mark ${/Maîtrise|Expertise/.test(s[2]||'')?'on':''}"></span><span>${esc(s[0])}<small>${esc(s[2]||'')}</small></span><b>${mod(s[1])}</b></div>`).join('')}</div></section><section class="glass-panel compact-panel combat-panel-v3"><div class="mini-head"><span>COMBAT ET AUTRES</span></div><div class="combat-list-v3"><div><span>🛡 CA</span><b>${state.ac}</b></div><label><span>♥ PV</span><input id="hpCurrent" type="number" value="${state.hp.current}" min="0"></label><label><span>♡ PV temporaires</span><input id="hpTemp" type="number" value="${state.hp.temp||0}" min="0"></label><div><span>✦ Initiative</span><b>${mod(state.initiative)}</b></div><div><span>🥾 Vitesse</span><b>${esc(state.speed)}</b></div><div><span>◉ Perception passive</span><b>${state.passives?.Perception??'—'}</b></div><div><span>✦ DD des sorts</span><b>${state.spellDC}</b></div><div><span>◌ Bonus attaque magique</span><b>+${state.spellAttack}</b></div></div></section></div><section class="sheet-resources glass-panel"><div class="resource-feature"><div><span class="eyebrow">INSPIRATION & RESSOURCES</span><strong>Utilisations actuelles</strong></div></div><div class="resource-grid-v3">${state.resources.map(r=>`<div class="resource-card-v3"><div><strong>${esc(r.name)}</strong><small>${esc(r.recharge||'')}</small></div><div class="resource-dots">${Array.from({length:r.max},(_,i)=>`<button class="resource-dot ${i<r.used?'used':''}" data-resource="${r.id}" data-resource-index="${i}" aria-label="${esc(r.name)} ${i+1}"></button>`).join('')}</div><span>${Math.max(0,r.max-r.used)} / ${r.max}</span></div>`).join('')}</div></section><details class="sheet-attacks glass-panel"><summary>⚔ Attaques et actions fréquentes</summary><div class="attack-list">${state.attacks.map(a=>`<div class="attack-row"><strong>${esc(a.name)}</strong><b>${esc(a.attack)}</b><span>${esc(a.effect)}</span></div>`).join('')}</div></details></section></div>`;
  $('#hpCurrent').onchange=e=>{state.hp.current=Math.max(0,Number(e.target.value||0));persist();renderHomeDashboard()};$('#hpTemp').onchange=e=>{state.hp.temp=Math.max(0,Number(e.target.value||0));persist()};$$('[data-resource]').forEach(b=>b.onclick=()=>{const r=state.resources.find(x=>x.id===b.dataset.resource),idx=Number(b.dataset.resourceIndex);if(!r)return;r.used=r.used>idx?idx:idx+1;persist();renderSheet()});updatePortraits();
}

/* ---------- features ---------- */
function renderFeatures(){
  const order=['Hadozee','Barde','Collège des Esprits','Don','Historique'],groups=[...new Set([...order.filter(g=>state.features.some(f=>f.group===g)),...state.features.map(f=>f.group).filter(g=>!order.includes(g))])];
  const labels={'Hadozee':'Ascendance — Hadozee','Barde':`Classe — Barde (niveau ${state.level})`,'Collège des Esprits':'Collège des Esprits — Sous-classe','Don':'Dons','Historique':`Historique — ${state.background||'Voyageur'}`};
  $('#featuresView').innerHTML=`<div class="features-v3"><div class="features-art-spacer" aria-hidden="true"></div><main class="features-center"><header class="screen-title-v3"><span class="eyebrow">TRAITS · APTITUDES DE CLASSE · DONS</span><h1>Aptitudes</h1></header>${groups.map(g=>{const fs=state.features.filter(f=>f.group===g);return `<details class="feature-drawer glass-panel" open><summary><div><span>${g==='Hadozee'?'🐾':g==='Barde'?'♫':g==='Collège des Esprits'?'🌀':g==='Don'?'✧':'📜'}</span><strong>${esc(labels[g]||g)}</strong></div><small>${fs.length} aptitude${fs.length>1?'s':''}</small></summary><div class="feature-drawer-body">${fs.map(f=>`<details class="feature-entry"><summary><div><strong>${esc(f.name)}</strong><small>${esc(f.subtitle||'')}</small></div><span>›</span></summary><p>${esc(f.text)}</p></details>`).join('')}</div></details>`}).join('')}</main><aside class="features-summary glass-panel"><span class="eyebrow">RÉSUMÉ DES APTITUDES</span><h2>Référence rapide</h2><div class="quick-stack"><div><span>Charisme</span><b>${mod(state.abilities?.CHA?.mod??0)}</b></div><div><span>DD des sorts</span><b>${state.spellDC}</b></div><div><span>Vitesse</span><b>${esc(state.speed)}</b></div><div><span>Perception passive</span><b>${state.passives?.Perception??'—'}</b></div><div><span>Langues</span><b>${state.languages?.length||0}</b></div></div><div class="summary-divider"></div><span class="eyebrow">RESSOURCES ACTIVES</span><div class="resource-summary-v3">${state.resources.slice(0,5).map(r=>`<div><span>${esc(r.name)}</span><div class="resource-dots">${Array.from({length:r.max},(_,i)=>`<button class="resource-dot ${i<r.used?'used':''}" data-feature-resource="${r.id}" data-resource-index="${i}"></button>`).join('')}</div><b>${Math.max(0,r.max-r.used)}/${r.max}</b></div>`).join('')}</div></aside></div>`;
  $$('[data-feature-resource]').forEach(b=>b.onclick=()=>{const r=state.resources.find(x=>x.id===b.dataset.featureResource),idx=Number(b.dataset.resourceIndex);if(!r)return;r.used=r.used>idx?idx:idx+1;persist();renderFeatures()});
}

/* ---------- spells ---------- */
function renderSpells(){
  const favorites=new Set(state.spellFavorites||[]);let list=state.spells.slice();
  if(spellFilter==='ritual')list=list.filter(s=>(s.tags||[]).some(t=>/rituel/i.test(t)));else if(spellFilter==='favorites')list=list.filter(s=>favorites.has(s.id));else if(spellFilter!=='all')list=list.filter(s=>Number(s.level)===Number(spellFilter));
  if(!selectedSpellId||!list.some(s=>s.id===selectedSpellId))selectedSpellId=list[0]?.id||state.spells[0]?.id||null;const selected=state.spells.find(s=>s.id===selectedSpellId)||null;
  const filters=[['all','Tous les sorts'],[0,'Tours de magie'],[1,'Niveau 1'],[2,'Niveau 2'],[3,'Niveau 3'],[4,'Niveau 4'],['ritual','Rituels'],['favorites','Favoris']];
  $('#spellsView').innerHTML=`<div class="spells-v3"><header class="spell-title-v3"><span class="spell-title-icon">🌀</span><div><span class="eyebrow">MAGIE & RITUELS</span><h1>Sorts</h1><p>« Les bons mots ouvrent plus de portes que les plus grandes clés. »</p></div></header><section class="slots-strip glass-panel"><span class="slots-label">EMPLACEMENTS DE SORTS</span>${[1,2,3,4].map(l=>{const max=Number(state.slotMax[l]||0),used=Number(state.slotUsed[l]||0);return `<div class="slot-group-v3"><b>N${l}</b><div class="slot-dots">${Array.from({length:max},(_,i)=>`<button class="slot-dot ${i<used?'used':''}" data-slot-level="${l}" data-slot-index="${i}" aria-label="Emplacement niveau ${l} ${i+1}"></button>`).join('')}</div><span>${Math.max(0,max-used)}/${max}</span></div>`}).join('')}</section><div class="spell-filter-v3">${filters.map(([id,l])=>`<button class="filter-chip ${String(spellFilter)===String(id)?'active':''}" data-spell-filter="${id}">${l}</button>`).join('')}</div><div class="spell-columns-v3"><section class="spell-list-v3 glass-panel">${list.map(s=>`<button class="spell-row-v3 ${s.id===selectedSpellId?'active':''}" data-spell-id="${s.id}"><span class="spell-school-icon">${favorites.has(s.id)?'★':'✦'}</span><span><strong>${esc(s.name)}</strong><small>${s.level===0?'Tour de magie':`Niveau ${s.level}`} · ${esc(s.school)}</small></span><i>›</i></button>`).join('')||'<div class="empty-state">Aucun sort dans ce filtre.</div>'}</section><section class="spell-detail-v3 glass-panel">${selected?`<div class="spell-detail-head"><div><span class="eyebrow">${selected.level===0?'TOUR DE MAGIE':`NIVEAU ${selected.level}`} · ${esc(selected.school)}</span><h2>${esc(selected.name)}</h2></div>${favorites.has(selected.id)?'<span class="favorite-mark">★</span>':''}</div><div class="spell-meta-v3"><div><span>🎯 Portée</span><b>${esc(selected.range)}</b></div><div><span>△ Composantes</span><b>${esc(selected.components)}</b></div><div><span>⌛ Durée</span><b>${esc(selected.duration)}</b></div><div><span>⏱ Incantation</span><b>${esc(selected.casting)}</b></div></div><div class="spell-tags-v3">${(selected.tags||[]).map(t=>`<span class="tag ${/concentration/i.test(t)?'concentration':''} ${/rituel/i.test(t)?'ritual':''}">${esc(t)}</span>`).join('')}</div><div class="spell-text-v3">${esc(selected.text)}</div><div class="spell-actions-v3"><button id="btnSpellFavorite" class="ghost">${favorites.has(selected.id)?'★ Retirer des favoris':'☆ Ajouter aux favoris'}</button><button id="btnSpellJournal" class="ghost">📖 Ajouter au journal</button><button id="btnCastSpell" class="primary">▶ Lancer le sort</button></div>`:'<div class="empty-state">Aucun sort sélectionné.</div>'}</section></div></div>`;
  $$('[data-spell-filter]').forEach(b=>b.onclick=()=>{spellFilter=b.dataset.spellFilter;renderSpells()});$$('[data-spell-id]').forEach(b=>b.onclick=()=>{selectedSpellId=b.dataset.spellId;renderSpells()});$$('[data-slot-level]').forEach(b=>b.onclick=()=>{const l=b.dataset.slotLevel,i=Number(b.dataset.slotIndex),used=Number(state.slotUsed[l]||0);state.slotUsed[l]=used>i?i:i+1;persist();renderSpells()});if(selected){$('#btnSpellFavorite').onclick=()=>toggleSpellFavorite(selected.id);$('#btnSpellJournal').onclick=()=>addSpellToJournal(selected);$('#btnCastSpell').onclick=()=>castSelectedSpell(selected)}
}

/* ---------- inventory ---------- */
function toggleSpellFavorite(id){state.spellFavorites=Array.isArray(state.spellFavorites)?state.spellFavorites:[];state.spellFavorites=state.spellFavorites.includes(id)?state.spellFavorites.filter(x=>x!==id):[...state.spellFavorites,id];persist();renderSpells()}
function addSpellToJournal(spell){state.journal.push({id:uid('note'),type:'note',title:`Sort · ${spell.name}`,text:`${spell.school} — ${spell.text}`,createdAt:nowStamp(),pinned:false});persist();toast('Sort ajouté au journal')}
function castSelectedSpell(spell){if(Number(spell.level)<=0)return toast(`${spell.name} lancé — aucun emplacement consommé`);const l=String(spell.level),max=Number(state.slotMax[l]||0),used=Number(state.slotUsed[l]||0);if(used>=max)return toast(`Aucun emplacement de niveau ${l} disponible`);state.slotUsed[l]=used+1;persist();renderSpells();toast(`${spell.name} lancé · emplacement N${l} consommé`)}

function itemIconType(item){return ITEM_TYPES[item.type]?item.type:'divers'}
function renderItemCard(item){return `<button class="item-card-v3 ${item.magical?'magic':''} ${item.attuned?'attuned':''} ${item.equipped?'equipped':''}" draggable="true" data-item-id="${item.id}" aria-label="${esc(item.name)}"><span class="item-badges">${item.attuned?'<i title="Lié">🔗</i>':''}${item.equipped?'<i title="Équipé">●</i>':''}${item.magical?'<i title="Magique">✦</i>':''}</span>${Number(item.qty||1)>1?`<span class="item-qty">${item.qty}</span>`:''}<img src="${itemIconType(item)}.png" alt=""><span class="item-card-footer"><strong>${esc(item.name)}</strong></span></button>`}
function inventoryFilterMatches(i){if(inventoryFilter==='all')return true;if(inventoryFilter==='magic')return !!i.magical;if(inventoryFilter==='weapon')return i.type.startsWith('arme_');if(inventoryFilter==='armor')return i.type.startsWith('armure_')||i.type.startsWith('bouclier');if(inventoryFilter==='consumable')return ['potion','consommable','munitions','munitions_magiques'].includes(i.type);if(inventoryFilter==='resource')return ['objet_merveilleux','baton_magique','baguette_magique','sceptre_magique','anneau'].includes(i.type);if(inventoryFilter==='document')return i.type==='parchemin';if(inventoryFilter==='misc')return ['divers'].includes(i.type);return true}
function renderInventory(){
  const attuned=state.items.filter(i=>i.equipped&&i.attuned).slice(0,3),equipped=state.items.filter(i=>i.equipped&&!i.attuned),bag=state.items.filter(i=>!i.equipped&&inventoryFilterMatches(i));
  const filters=[['all','Tous'],['weapon','Armes'],['armor','Armures'],['consumable','Consommables'],['magic','Objets magiques'],['resource','Ressources'],['document','Documents'],['misc','Divers']];
  $('#inventoryView').innerHTML=`<div class="inventory-v3"><section class="equipment-v3"><div class="inventory-title-v3"><div><span class="eyebrow">ÉQUIPEMENT</span><h1>Équipement</h1><p>${esc(state.name)} · Niveau ${state.level} · ${esc(state.className)} ${esc(state.species)}</p></div><button id="btnEquipmentSettings" class="ghost">${icon('crayon')} Modifier</button></div><div class="character-stage-v3 drop-zone" data-drop-target="equipped"><img data-character-portrait class="character-png-v3" src="${state.portrait}" alt="${esc(state.name)}"></div><div class="equipment-label-v3"><span>OBJETS LIÉS</span><small>Harmonisation · ${attuned.length}/3</small></div><div class="attuned-slots-v3 drop-zone" data-drop-target="attuned">${attuned.map(renderItemCard).join('')}${Array.from({length:Math.max(0,3-attuned.length)},()=>'<div class="empty-attuned-slot"><span>🔗</span><small>Emplacement lié</small></div>').join('')}</div><div class="equipment-label-v3"><span>AUTRES ÉQUIPEMENTS</span></div><div class="equipped-grid-v3 drop-zone" data-drop-target="equipped">${equipped.map(renderItemCard).join('')||'<div class="empty-state">Aucun autre équipement.</div>'}</div></section><section class="possessions-v3 glass-panel"><div class="possessions-head-v3"><div><span class="eyebrow">POSSESSIONS</span><h1>Inventaire</h1><p>Tous vos objets, trésors et curiosités.</p></div><div class="money-v3"><strong>${state.money.gp||0} PO</strong><span>${state.money.pp||0} PP · ${state.money.sp||0} PA · ${state.money.cp||0} PC</span></div></div><div class="inventory-toolbar-v3"><div class="inventory-filters-v3">${filters.map(([id,l])=>`<button class="filter-chip ${inventoryFilter===id?'active':''}" data-inventory-filter="${id}">${l}</button>`).join('')}</div><div class="inventory-tools-v3"><button id="btnAddItem" class="primary">${icon('plus')} Ajouter</button><button id="btnImportItem" class="violet">${icon('fleche_bas')} Importer</button></div></div><div class="inventory-grid-v3 drop-zone" data-drop-target="bag">${bag.map(renderItemCard).join('')||'<div class="empty-state">Aucun objet dans ce filtre.</div>'}</div></section></div>`;
  $('#btnEquipmentSettings').onclick=openEquipmentSettings;$('#btnAddItem').onclick=()=>openItemEditor();$('#btnImportItem').onclick=()=>$('#itemImportFile').click();$$('[data-inventory-filter]').forEach(b=>b.onclick=()=>{inventoryFilter=b.dataset.inventoryFilter;renderInventory()});bindInventoryDnD();$$('[data-item-id]').forEach(card=>card.onclick=()=>{if(Date.now()<suppressItemClickUntil)return;openItemPopover(card.dataset.itemId,card)});updatePortraits();
}
function bindInventoryDnD(){
  const clearTargets=()=>$$('.pointer-over,.drag-over').forEach(x=>x.classList.remove('pointer-over','drag-over'));
  $$('[data-item-id]').forEach(card=>{
    card.ondragstart=e=>{draggedItemId=card.dataset.itemId;e.dataTransfer?.setData('text/plain',draggedItemId);if(e.dataTransfer)e.dataTransfer.effectAllowed='move'};card.ondragend=()=>{draggedItemId=null;clearTargets()};card.ondragover=e=>e.preventDefault();card.ondrop=e=>{e.preventDefault();const source=draggedItemId||e.dataTransfer?.getData('text/plain');reorderItem(source,card.dataset.itemId)};
    card.onpointerdown=e=>{if(e.pointerType==='mouse'&&e.button!==0)return;const id=card.dataset.itemId,startX=e.clientX,startY=e.clientY;let dragging=false,cancelled=false;let timer=setTimeout(()=>{if(cancelled)return;dragging=true;pointerDrag={id,card};card.classList.add('dragging');document.body.classList.add('inventory-dragging');try{card.setPointerCapture(e.pointerId)}catch{}},170);
      const move=ev=>{const dist=Math.hypot(ev.clientX-startX,ev.clientY-startY);if(!dragging&&dist>9){cancelled=true;clearTimeout(timer);cleanup(false);return}if(dragging){ev.preventDefault();clearTargets();const hit=document.elementFromPoint(ev.clientX,ev.clientY),target=hit?.closest?.('[data-item-id],[data-drop-target]');if(target&&target!==card)target.classList.add('pointer-over')}};
      const cleanup=removeAll=>{card.removeEventListener('pointermove',move);if(removeAll){card.removeEventListener('pointerup',up);card.removeEventListener('pointercancel',up)}};
      const up=ev=>{clearTimeout(timer);cleanup(true);if(!dragging)return;ev.preventDefault();suppressItemClickUntil=Date.now()+350;const hit=document.elementFromPoint(ev.clientX,ev.clientY),targetCard=hit?.closest?.('[data-item-id]'),zone=hit?.closest?.('[data-drop-target]');card.classList.remove('dragging');document.body.classList.remove('inventory-dragging');clearTargets();pointerDrag=null;if(targetCard&&targetCard.dataset.itemId!==id)reorderItem(id,targetCard.dataset.itemId);else if(zone)moveItemToZone(id,zone.dataset.dropTarget)};
      card.addEventListener('pointermove',move,{passive:false});card.addEventListener('pointerup',up,{once:true});card.addEventListener('pointercancel',up,{once:true})
    }
  });
  $$('[data-drop-target]').forEach(z=>{z.ondragover=e=>{e.preventDefault();z.classList.add('drag-over')};z.ondragleave=()=>z.classList.remove('drag-over');z.ondrop=e=>{e.preventDefault();z.classList.remove('drag-over');const id=draggedItemId||e.dataTransfer?.getData('text/plain');moveItemToZone(id,z.dataset.dropTarget)}})
}
function reorderItem(source,target){if(!source||!target||source===target)return;const a=state.items.findIndex(x=>x.id===source),b=state.items.findIndex(x=>x.id===target);if(a<0||b<0)return;const [it]=state.items.splice(a,1);state.items.splice(b,0,it);persist();renderInventory()}
function moveItemToZone(id,zone){const it=state.items.find(x=>x.id===id);if(!it)return;if(zone==='bag'){it.equipped=false;it.attuned=false}else if(zone==='equipped'){it.equipped=true;it.attuned=false}else if(zone==='attuned'){if(state.items.filter(x=>x.equipped&&x.attuned&&x.id!==id).length>=3)return toast('3 objets liés maximum');it.equipped=true;it.attuned=true}persist();renderInventory()}
function openItemPopover(id,card){const item=state.items.find(x=>x.id===id);if(!item)return;currentItemId=id;const p=$('#itemPopover'),r=card.getBoundingClientRect();p.innerHTML=`<div class="popover-head"><div><span class="eyebrow">${esc(ITEM_TYPES[item.type]||'OBJET')}</span><h3>${esc(item.name)}</h3></div><button class="icon-button small" id="btnPopoverEdit" aria-label="Modifier">${icon('crayon')}</button></div><div class="popover-tags">${item.rarity?`<span class="tag">${esc(item.rarity)}</span>`:''}${item.magical?'<span class="tag magic">Magique</span>':''}${item.attuned?'<span class="tag">🔗 Lié</span>':''}${item.equipped?'<span class="tag">Équipé</span>':''}</div><div class="popover-text"><b>${esc(item.summary||'')}</b><p>${esc(item.description||'Aucune description.')}</p></div><div class="popover-meta-v3"><span>Quantité <b>${item.qty||1}</b></span><span>Poids <b>${esc(item.weight||'—')}</b></span><span>Valeur <b>${esc(item.value||'—')}</b></span>${item.maxCharges!==''?`<span>Charges <b>${esc(item.charges||0)}/${esc(item.maxCharges||0)}</b></span>`:''}</div><div class="popover-actions"><button id="btnPopoverExport" class="violet">${icon('fleche_haut')} Exporter</button></div>`;p.classList.remove('hidden','above');p.setAttribute('aria-hidden','false');p.style.visibility='hidden';requestAnimationFrame(()=>{const h=p.offsetHeight||260,w=p.offsetWidth||360;let top=r.bottom+8;if(top+h>window.innerHeight-78){top=Math.max(10,r.top-h-8);p.classList.add('above')}p.style.left=`${Math.min(window.innerWidth-w-10,Math.max(10,r.left))}px`;p.style.top=`${top}px`;p.style.visibility='visible'});$('#btnPopoverEdit').onclick=()=>openItemEditor(id);$('#btnPopoverExport').onclick=()=>exportItem(id)}
function closeItemPopover(){$('#itemPopover').classList.add('hidden');$('#itemPopover').setAttribute('aria-hidden','true')}
function openItemEditor(id=null){closeItemPopover();currentItemId=id;const item=id?state.items.find(x=>x.id===id):{id:'',name:'',type:'divers',rarity:'',qty:1,magical:false,attuned:false,equipped:false,weight:'',value:'',charges:'',maxCharges:'',summary:'',description:''};const f=$('#itemEditorForm');$('#itemEditorTitle').textContent=id?'Modifier l’objet':'Nouvel objet';for(const [k,v] of Object.entries(item)){const e=f.elements[k];if(!e)continue;if(e.type==='checkbox')e.checked=!!v;else e.value=v??''}$('#btnDeleteItem').style.visibility=id?'visible':'hidden';$('#btnExportItem').style.visibility=id?'visible':'hidden';$('#itemEditorDialog').showModal()}
function saveItemForm(f){const fd=new FormData(f),id=fd.get('id')||uid('itm');let item=state.items.find(x=>x.id===id);if(!item){item={id};state.items.push(item)}Object.assign(item,{name:String(fd.get('name')||'Objet'),type:String(fd.get('type')||'divers'),rarity:String(fd.get('rarity')||''),qty:Math.max(1,Number(fd.get('qty')||1)),magical:f.elements.magical.checked,attuned:f.elements.attuned.checked,equipped:f.elements.equipped.checked,weight:String(fd.get('weight')||''),value:String(fd.get('value')||''),charges:fd.get('charges')===''?'':Number(fd.get('charges')),maxCharges:fd.get('maxCharges')===''?'':Number(fd.get('maxCharges')),summary:String(fd.get('summary')||''),description:String(fd.get('description')||'')});if(item.attuned)item.equipped=true;persist();$('#itemEditorDialog').close();renderInventory()}
function exportItem(id=currentItemId){const item=state.items.find(x=>x.id===id);if(!item)return;downloadBlob(`Cockpit-Objet-${safeFileName(item.name)}.json`,new Blob([JSON.stringify({format:'cockpit-player-item',formatVersion:1,item},null,2)],{type:'application/json'}))}
async function importItemFile(file){const raw=JSON.parse(await file.text()),it=raw.item||raw;if(!it?.name)throw new Error('Objet invalide');it.id=uid('itm');state.items.push(it);persist();renderInventory();toast(`Objet « ${it.name} » importé`)}
function openEquipmentSettings(){const f=$('#equipmentSettingsForm');f.elements.attuneColor.value=state.attuneColor||'#c69a55';$('#equipmentSettingsDialog').showModal()}

/* ---------- Journal ---------- */
function renderJournal(){
  const types=[['all','Tous'],['quest','Quêtes'],['clue','Indices'],['npc','PNJ'],['place','Lieux'],['memory','Souvenirs'],['note','Notes']],counts=state.journal.reduce((a,j)=>(a[j.type]=(a[j.type]||0)+1,a),{}),filtered=state.journal.filter(j=>journalFilter==='all'||j.type===journalFilter).sort((a,b)=>(Number(b.pinned)-Number(a.pinned))||String(b.createdAt).localeCompare(String(a.createdAt)));
  $('#journalView').innerHTML=`<div class="journal-v3"><aside class="journal-filters-v3 glass-panel"><span class="eyebrow">FILTRES</span><div class="journal-filter-list">${types.map(([id,l])=>`<button class="journal-filter-btn ${journalFilter===id?'active':''}" data-journal-filter="${id}"><span>${id==='quest'?'📜':id==='clue'?'🔎':id==='npc'?'👤':id==='place'?'⛰':id==='memory'?'✦':id==='note'?'📝':'📖'}</span><b>${l}</b><small>${id==='all'?state.journal.length:(counts[id]||0)}</small></button>`).join('')}</div><div class="journal-activity"><span class="eyebrow">ACTIVITÉ RÉCENTE</span><p><b>${state.journal.length}</b> notes conservées</p><p><b>${state.journal.filter(j=>j.pinned).length}</b> épinglées</p><p><b>${counts.place||0}</b> lieux consignés</p><p><b>${counts.npc||0}</b> PNJ consignés</p></div></aside><main class="journal-main-v3"><header class="screen-title-v3 journal-title-v3"><span class="eyebrow">ÉCRIRE, C’EST SE SOUVENIR DEUX FOIS</span><h1>Journal</h1></header><section class="quick-note-v3 glass-panel"><span class="quick-note-icon">🪶</span><input id="quickNoteText" placeholder="Écrire une note, un souvenir, une idée…"><select id="quickNoteType"><option value="note">Note</option><option value="quest">Quête</option><option value="clue">Indice</option><option value="npc">PNJ</option><option value="place">Lieu</option><option value="memory">Souvenir</option></select><button id="btnQuickAddNote" class="primary">＋ Ajouter</button></section><div class="journal-list-head"><span>MES NOTES</span><button id="btnExportJournal" class="violet">${icon('fleche_haut')} Exporter</button></div><section class="journal-list-v3">${filtered.map(j=>`<article class="journal-entry-v3 ${j.pinned?'pinned':''}" data-note-row="${j.id}"><div class="journal-date">${new Date(j.createdAt).toLocaleString('fr-FR')}</div><div class="journal-copy"><div><span class="tag">${esc(types.find(x=>x[0]===j.type)?.[1]||j.type)}</span><h3>${esc(j.title||'Note')}</h3></div><p>${esc(j.text)}</p></div><div class="journal-entry-actions"><button data-note-pin="${j.id}" aria-label="Épingler">${j.pinned?'📌':'📍'}</button><button data-note-edit="${j.id}" aria-label="Modifier">✏</button><button data-note-delete="${j.id}" aria-label="Supprimer">🗑</button></div></article>`).join('')||'<div class="empty-state">Aucune note dans ce filtre.</div>'}</section></main></div>`;
  $$('[data-journal-filter]').forEach(b=>b.onclick=()=>{journalFilter=b.dataset.journalFilter;renderJournal()});$('#btnQuickAddNote').onclick=()=>{const input=$('#quickNoteText'),text=input.value.trim();if(!text)return toast('Écris une note');state.journal.push({id:uid('note'),type:$('#quickNoteType').value,title:'',text,createdAt:nowStamp(),pinned:false});persist();renderJournal()};$('#btnExportJournal').onclick=exportJournal;$$('[data-note-edit]').forEach(b=>b.onclick=()=>openNoteEditor(b.dataset.noteEdit));$$('[data-note-pin]').forEach(b=>b.onclick=()=>toggleNotePin(b.dataset.notePin));$$('[data-note-delete]').forEach(b=>b.onclick=()=>deleteNoteById(b.dataset.noteDelete));
}
function toggleNotePin(id){const n=state.journal.find(x=>x.id===id);if(!n)return;n.pinned=!n.pinned;persist();renderJournal()}
async function deleteNoteById(id){const n=state.journal.find(x=>x.id===id);if(!n)return;if(await askConfirm(`Supprimer « ${n.title||'cette note'} » ?`)){state.journal=state.journal.filter(x=>x.id!==id);persist();renderJournal()}}
function openNoteEditor(id=null){currentNoteId=id;const n=id?state.journal.find(x=>x.id===id):{id:'',type:'note',title:'',text:''};const f=$('#noteEditorForm');f.elements.id.value=n.id||'';f.elements.type.value=n.type||'note';f.elements.title.value=n.title||'';f.elements.text.value=n.text||'';$('#btnDeleteNote').style.visibility=id?'visible':'hidden';$('#noteEditorDialog').showModal()}
function saveNoteForm(f){const fd=new FormData(f),id=fd.get('id')||uid('note');let n=state.journal.find(x=>x.id===id);if(!n){n={id,createdAt:nowStamp()};state.journal.push(n)}Object.assign(n,{type:String(fd.get('type')||'note'),title:String(fd.get('title')||''),text:String(fd.get('text')||'')});persist();$('#noteEditorDialog').close();renderJournal()}
function exportJournal(){const rows=state.journal.slice().sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt)));const txt=[`Journal de ${state.name}`,`Exporté le ${new Date().toLocaleString('fr-FR')}`,'',...rows.flatMap((j,i)=>[`${i+1}. ${j.title||'Note'} [${j.type}]`,`   ${new Date(j.createdAt).toLocaleString('fr-FR')}`,`   ${j.text}`,''])].join('\n');downloadBlob(`Journal-${safeFileName(state.name)}.txt`,new Blob([txt],{type:'text/plain;charset=utf-8'}))}

/* ---------- Illustrations ---------- */
const DEFAULT_ILLUS_CATS=[['npc','PNJ'],['adversary','Adversaires'],['places','Lieux'],['items','Objets'],['misc','Divers'],['clues','Indices']];let illustrationCats=[...DEFAULT_ILLUS_CATS];
async function loadIllustrationCats(){const r=await dbGet('meta','illustrationCategories');const custom=Array.isArray(r?.value)?r.value:[];illustrationCats=[...DEFAULT_ILLUS_CATS,...custom]}
async function renderIllustrations(){
  const root=$('#illustrationsView');root.innerHTML='<div class="empty-state">Chargement…</div>';await loadIllustrationCats();const items=(await dbAll('illustrations')).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));illustrationObjectUrls.forEach(URL.revokeObjectURL);illustrationObjectUrls=[];const visible=illustrationFilter==='all'?items:items.filter(x=>(x.category||'misc')===illustrationFilter);
  root.innerHTML=`<div class="illustrations-v3"><aside class="illustration-sidebar-v3 glass-panel"><div><span class="eyebrow">CATÉGORIES</span><h2>Illustrations</h2></div><button class="illus-cat-btn ${illustrationFilter==='all'?'active':''}" data-illus-filter="all"><span>🖼</span><b>Toutes</b><small>${items.length}</small></button>${illustrationCats.map(([id,label])=>{const count=items.filter(x=>(x.category||'misc')===id).length;return `<button class="illus-cat-btn ${illustrationFilter===id?'active':''}" data-illus-filter="${id}"><span>${id==='npc'?'👤':id==='adversary'?'👹':id==='places'?'🏔':id==='items'?'⚗':'◆'}</span><b>${esc(label)}</b><small>${count}</small></button>`}).join('')}<button id="btnIllCategorySide" class="blue illus-new-cat">＋ Nouvelle catégorie</button></aside><main class="illustration-main-v3"><div class="illustration-hero-v3"><div><span class="eyebrow">BIBLIOTHÈQUE PERSONNELLE</span><h1>Illustrations</h1><p>Vos images pour enrichir vos parties.</p></div><div class="illustration-actions-v3"><button id="btnIllImport" class="violet">${icon('fleche_bas')} Importer</button><button id="btnIllExport" class="violet" ${illustrationSelected.size?'':'disabled'}>${icon('fleche_haut')} Exporter${illustrationSelected.size?` (${illustrationSelected.size})`:''}</button><button id="btnIllDelete" class="danger" ${illustrationSelected.size?'':'disabled'}>🗑 Supprimer</button><button id="btnIllMove" class="green" ${illustrationSelected.size?'':'disabled'}>${illustrationMoveMode?'✓ Choisir la catégorie':'↔ Déplacer'}</button><button id="btnIllCategory" class="blue">＋ Catégorie</button></div></div><section class="illustration-masonry-v3">${visible.map(x=>{const u=URL.createObjectURL(x.blob);illustrationObjectUrls.push(u);return `<button class="illustration-card-v3 ${illustrationSelected.has(x.id)?'selected':''} ${illustrationMoveMode&&illustrationSelected.has(x.id)?'moving':''} ${x.sentAt?'sent':''}" data-illus-id="${x.id}"><img src="${u}" alt="${esc(x.name)}"><span>${esc(x.name)}</span>${x.sentAt?'<i>ENVOYÉE</i>':''}</button>`}).join('')||'<div class="empty-state">Aucune illustration dans cette catégorie.</div>'}</section></main></div>`;
  $('#btnIllImport').onclick=()=>$('#illustrationImportFile').click();$('#btnIllCategory').onclick=$('#btnIllCategorySide').onclick=()=>$('#illustrationCategoryDialog').showModal();$('#btnIllDelete').onclick=()=>openIllustrationDelete();$('#btnIllMove').onclick=()=>{illustrationMoveMode=!illustrationMoveMode;renderIllustrations()};$('#btnIllExport').onclick=()=>exportSelectedIllustrations(items);$$('[data-illus-id]').forEach(b=>b.onclick=()=>{const id=b.dataset.illusId;if(illustrationSelected.has(id))illustrationSelected.delete(id);else illustrationSelected.add(id);renderIllustrations()});$$('[data-illus-filter]').forEach(b=>b.onclick=()=>{const cat=b.dataset.illusFilter;if(illustrationMoveMode&&illustrationSelected.size&&cat!=='all')return moveIllustrations(cat);illustrationFilter=cat;renderIllustrations()});
}
function illustrationOptions(selected='misc'){return illustrationCats.map(([v,l])=>`<option value="${v}" ${v===selected?'selected':''}>${esc(l)}</option>`).join('')}
function prepareIllustrationImport(files){pendingIllustrationFiles=[...files].filter(f=>f.type.startsWith('image/'));if(!pendingIllustrationFiles.length)return;$('#illustrationImportRows').innerHTML=pendingIllustrationFiles.map((f,i)=>`<div class="illustration-import-row"><div><strong>${esc(f.name)}</strong><small class="muted">${Math.round(f.size/1024)} Ko</small></div><select data-illus-import-cat="${i}">${illustrationOptions('misc')}</select></div>`).join('');$('#illustrationImportDialog').showModal()}
async function saveIllustrationImport(){const recs=pendingIllustrationFiles.map((f,i)=>({id:uid('ill'),name:f.name,category:$(`[data-illus-import-cat="${i}"]`).value,blob:f,createdAt:nowStamp(),sentAt:null}));for(const r of recs)await dbPut('illustrations',r);pendingIllustrationFiles=[];$('#illustrationImportDialog').close();renderIllustrations();toast(`${recs.length} illustration(s) importée(s)`)}
async function createIllustrationCategory(name){name=String(name||'').trim();if(!name)return;const meta=await dbGet('meta','illustrationCategories');const custom=Array.isArray(meta?.value)?meta.value:[];custom.push([uid('cat'),name]);await dbPut('meta',{key:'illustrationCategories',value:custom});$('#illustrationCategoryDialog').close();renderIllustrations()}
async function moveIllustrations(cat){const items=await dbAll('illustrations');for(const x of items.filter(x=>illustrationSelected.has(x.id))){x.category=cat;await dbPut('illustrations',x)}illustrationSelected.clear();illustrationMoveMode=false;renderIllustrations();toast('Illustrations déplacées')}
function openIllustrationDelete(){$('#illustrationDeleteMessage').textContent=`Supprimer ${illustrationSelected.size} illustration(s) sélectionnée(s) ?`;$('#illustrationDeleteDialog').showModal()}
async function confirmIllustrationDelete(){for(const id of illustrationSelected)await dbDelete('illustrations',id);illustrationSelected.clear();$('#illustrationDeleteDialog').close();renderIllustrations()}
async function exportSelectedIllustrations(items){const selected=items.filter(x=>illustrationSelected.has(x.id));if(!selected.length)return;const files=selected.map((x,i)=>new File([x.blob],x.name||`illustration-${i+1}.jpg`,{type:x.blob.type||'image/jpeg'}));try{if(navigator.share&&(!navigator.canShare||navigator.canShare({files}))){await navigator.share({title:`Cockpit Joueur · ${state.name}`,files});const stamp=nowStamp();for(const x of selected){x.sentAt=stamp;await dbPut('illustrations',x)}illustrationSelected.clear();renderIllustrations();return}}catch(e){if(e?.name==='AbortError')return}toast('Le partage de fichiers n’est pas disponible ici')}

/* ---------- search ---------- */
function openSearch(){const i=$('#globalSearchInput');$('#searchDialog').showModal();i.value='';i.placeholder=VIEW_SEARCH_LABELS[currentView]||'Rechercher…';$('#globalSearchResults').innerHTML='';setTimeout(()=>i.focus(),40)}
async function doSearch(q){q=q.trim().toLowerCase();if(!q)return $('#globalSearchResults').innerHTML='';const results=[],all=currentView==='home';if(all||currentView==='sheet'){Object.entries(state.abilities).filter(([k,a])=>(k+' '+a.score+' '+a.mod).toLowerCase().includes(q)).forEach(([k])=>results.push({view:'sheet',label:`Caractéristique · ${k}`}));state.skills.filter(x=>x.join(' ').toLowerCase().includes(q)).forEach(x=>results.push({view:'sheet',label:`Compétence · ${x[0]}`}))}if(all||currentView==='features')state.features.filter(x=>(x.name+' '+x.group+' '+x.text).toLowerCase().includes(q)).forEach(x=>results.push({view:'features',label:`Aptitude · ${x.name}`}));if(all||currentView==='spells')state.spells.filter(x=>(x.name+' '+x.school+' '+x.text).toLowerCase().includes(q)).forEach(x=>results.push({view:'spells',label:`Sort · ${x.name}`,id:x.id}));if(all||currentView==='inventory')state.items.filter(x=>(x.name+' '+x.summary+' '+x.description).toLowerCase().includes(q)).forEach(x=>results.push({view:'inventory',label:`Objet · ${x.name}`,id:x.id}));if(all||currentView==='journal')state.journal.filter(x=>(x.title+' '+x.text).toLowerCase().includes(q)).forEach(x=>results.push({view:'journal',label:`Journal · ${x.title||'Note'}`,id:x.id}));if(all||currentView==='illustrations'){const ill=await dbAll('illustrations');ill.filter(x=>String(x.name||'').toLowerCase().includes(q)).forEach(x=>results.push({view:'illustrations',label:`Illustration · ${x.name}`,id:x.id}))}$('#globalSearchResults').innerHTML=results.slice(0,30).map((r,i)=>`<button class="search-result" data-search-index="${i}"><strong>${esc(r.label)}</strong></button>`).join('')||'<div class="empty-state">Aucun résultat.</div>';$$('[data-search-index]').forEach(b=>b.onclick=()=>{const r=results[Number(b.dataset.searchIndex)];$('#searchDialog').close();if(r.view==='spells'&&r.id)selectedSpellId=r.id;switchView(r.view);if(r.view==='inventory'&&r.id)setTimeout(()=>{const card=$(`[data-item-id="${r.id}"]`);if(card)openItemPopover(r.id,card)},80)})}

/* ---------- global render ---------- */
function renderAll(){renderTop();renderSlots();renderThemes();renderView(currentView);applyBackgrounds()}

/* ---------- events ---------- */
$$('.nav-btn[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('#btnHome').onclick=()=>openHome('characters');$('#btnSettings').onclick=()=>openHome('theme');$('#btnCloseHome').onclick=closeHome;$('#btnGlobalSearch').onclick=openSearch;$('#globalSearchInput').oninput=e=>doSearch(e.target.value);$('#btnSaveCharacter').onclick=saveCurrentCharacter;$('#btnImportCharacter').onclick=()=>$('#characterImportFile').click();
$('#characterImportFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await importCharacterFile(f)}catch(err){console.error(err);toast(err.message||'Import impossible')}e.target.value=''};
$('#itemImportFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await importItemFile(f)}catch(err){toast('Objet incompatible')}e.target.value=''};
$('#backgroundImportFile').onchange=async e=>{const f=e.target.files[0];if(f&&pendingBackgroundView)await importBackground(pendingBackgroundView,f);e.target.value='';pendingBackgroundView=null};
$('#portraitImportFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;await dbPut('portraits',{id:`portrait:${state.id}`,blob:f});if(portraitObjectUrl){URL.revokeObjectURL(portraitObjectUrl);portraitObjectUrl=null}updatePortraits();e.target.value='';toast('Illustration du personnage mise à jour')};
$('#btnImportPortrait').onclick=()=>$('#portraitImportFile').click();$('#btnResetPortrait').onclick=async()=>{await dbDelete('portraits',`portrait:${state.id}`);if(portraitObjectUrl){URL.revokeObjectURL(portraitObjectUrl);portraitObjectUrl=null}updatePortraits();toast('Illustration réinitialisée')};
$('#equipmentSettingsForm').onsubmit=e=>{e.preventDefault();state.attuneColor=e.target.elements.attuneColor.value;persist();document.documentElement.style.setProperty('--attune',state.attuneColor);$('#equipmentSettingsDialog').close();renderInventory()};
$('#itemEditorForm').onsubmit=e=>{e.preventDefault();saveItemForm(e.target)};$('#btnDeleteItem').onclick=async()=>{if(!currentItemId)return;const it=state.items.find(x=>x.id===currentItemId);if(it&&await askConfirm(`Supprimer « ${it.name} » ?`)){state.items=state.items.filter(x=>x.id!==currentItemId);persist();$('#itemEditorDialog').close();renderInventory()}};$('#btnExportItem').onclick=()=>exportItem(currentItemId);
$('#noteEditorForm').onsubmit=e=>{e.preventDefault();saveNoteForm(e.target)};$('#btnDeleteNote').onclick=()=>{if(!currentNoteId)return;state.journal=state.journal.filter(x=>x.id!==currentNoteId);persist();$('#noteEditorDialog').close();renderJournal()};
$('#illustrationImportFile').onchange=e=>{prepareIllustrationImport(e.target.files);e.target.value=''};$('#illustrationImportForm').onsubmit=async e=>{e.preventDefault();await saveIllustrationImport()};$('#illustrationCategoryForm').onsubmit=async e=>{e.preventDefault();await createIllustrationCategory(new FormData(e.target).get('name'));e.target.reset()};$('#btnCancelIllustrationDelete').onclick=()=>$('#illustrationDeleteDialog').close();$('#btnConfirmIllustrationDelete').onclick=confirmIllustrationDelete;
$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close)?.close());document.addEventListener('click',e=>{if(!e.target.closest('.item-popover')&&!e.target.closest('[data-item-id]'))closeItemPopover()});

/* setup type select */
$('#itemTypeSelect').innerHTML=Object.entries(ITEM_TYPES).map(([v,l])=>`<option value="${v}">${l}</option>`).join('');
applyTheme(localStorage.getItem(THEME_KEY)||'emerald');renderAll();switchView('home');if('serviceWorker' in navigator)navigator.serviceWorker.register('service-worker.js?v=0.3.0').catch(()=>{});
